ALTER TABLE "recreio"."safety_reports" DROP CONSTRAINT "recreio_safety_report_evidence";--> statement-breakpoint
ALTER TABLE "recreio"."safety_reports" ADD CONSTRAINT "recreio_safety_report_evidence" CHECK (("recreio"."safety_reports"."evidence_kind" in ('pedido','mundo') and "recreio"."safety_reports"."evidence_id" is not null and "recreio"."safety_reports"."evidence_revision" is null) or ("recreio"."safety_reports"."evidence_kind"='amizade' and "recreio"."safety_reports"."evidence_revision" is not null and "recreio"."safety_reports"."evidence_revision">0 and "recreio"."safety_reports"."evidence_id" is null) or ("recreio"."safety_reports"."evidence_kind"='protecao' and "recreio"."safety_reports"."evidence_id" is null and "recreio"."safety_reports"."evidence_revision" is null));